import java.util.*;

public class Test {
    static int r, c;
    static Scanner in = new Scanner(System.in);
    static long[][] C = new long[64][64];
    static long best = Long.MAX_VALUE;
    static Map<Long, Long> cache = new TreeMap<>();
    static char[] cs;

    static void dfs(long x, long y, int v1, int v2) {
        long d = Math.abs(x - y);
        if (best <= 1 || d - C[v1][r] * C[v2][r] >= best) return;
        if (v1 == r - 1 && v2 == r - 1) {
            if (d < best) best = d;
            return;
        }
        if (v1 >= r) {
            long c1 = C[v1][r] - C[v1 - 1][r];
            long s2 = C[v2][r];
            dfs(x, y + c1 * s2, v1 - 1, v2);
        }
        if (v2 >= r) {
            long s1 = C[v1][r];
            long c2 = C[v2][r] - C[v2 - 1][r];
            dfs(x + s1 * c2, y, v1, v2 - 1);
        }
    }

    static long solve(long x, long y, int v1, int v2) {
        long k = x * 10000 + v1 * 100 + v2;
        Long got = cache.get(k);
        if (got != null) return got;
        long val = 0L;
        long d = Math.abs(x - y);
        if (d - C[v1][r] * C[v2][r] > best) {
            cache.put(k, val);
            return val;
        }
        if (v1 == 0 && v2 == 0) return 1L;
        char ch = cs[v1 + v2 - 1];
        if (v1 > 0 && ch != 'B') {
            long c1 = C[v1][r] - C[v1 - 1][r];
            long s2 = C[v2][r];
            val += solve(x, y + c1 * s2, v1 - 1, v2);
        }
        if (v2 > 0 && ch != 'A') {
            long s1 = C[v1][r];
            long c2 = C[v2][r] - C[v2 - 1][r];
            val += solve(x + s1 * c2, y, v1, v2 - 1);
        }
        cache.put(k, val);
        return val;
    }

    static void start() {
        r = in.nextInt();
        c = in.nextInt();
        in.nextLine();
        cs = in.nextLine().toCharArray();
        int n = 2 * (r + c);
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                if (j == 0) C[i][j] = 1L;
                else if (i == 0) C[i][j] = 0L;
                else C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
            }
        }
        int v1 = r + c, v2 = r + c;
        long x = 0, y = 0;
        while (v1 >= r && v2 >= r) {
            if (x > y) {
                long c1 = C[v1][r] - C[v1 - 1][r];
                long s2 = C[v2][r];
                y += c1 * s2;
                v1--;
            } else {
                long s1 = C[v1][r];
                long c2 = C[v2][r] - C[v2 - 1][r];
                x += s1 * c2;
                v2--;
            }
        }
        best = Math.abs(x - y);
        dfs(0, 0, r + c, r + c);
        System.out.println(solve(0, 0, r + c, r + c));
    }

    public static void main(String[] args) {
        start();
    }
}
